DELIMITER $$
CREATE FUNCTION fn_amount(p_ono INT)
  RETURNS DECIMAL(10,2)
  READS SQL DATA
BEGIN
  DECLARE amt DECIMAL(10,2);
  SELECT g.price * o.qty INTO amt
    FROM orders o JOIN goods g ON o.gno = g.gno
    WHERE o.ono = p_ono;
  RETURN amt;
END $$
CREATE PROCEDURE sp_order(IN p_gno CHAR(2),
  IN p_qty INT, OUT p_msg VARCHAR(20))
BEGIN
  DECLARE s INT DEFAULT 0;
  SELECT stock INTO s FROM goods
    WHERE gno = p_gno;
  IF s >= p_qty THEN
    INSERT INTO orders(gno, qty, odate)
      VALUES (p_gno, p_qty, CURDATE());
    UPDATE goods SET stock = stock - p_qty
      WHERE gno = p_gno;
    SET p_msg = '下单成功';
  ELSE
    SET p_msg = '库存不足';
  END IF;
END $$
DELIMITER ;
SELECT ono, gno, fn_amount(ono) AS 金额
  FROM orders;
CALL sp_order('G2', 3, @m1);
CALL sp_order('G1', 5, @m2);
SELECT @m1, @m2;
SELECT * FROM goods;

DELIMITER $$
CREATE FUNCTION fn_dept_avg(p_dno CHAR(2))
  RETURNS DECIMAL(10,2)
  READS SQL DATA
BEGIN
  RETURN (SELECT AVG(salary) FROM emp
          WHERE dno = p_dno);
END $$
CREATE PROCEDURE sp_raise(OUT p_n INT)
BEGIN
  DECLARE v_eno CHAR(2);
  DECLARE v_sal DECIMAL(8,2);
  DECLARE done INT DEFAULT 0;
  DECLARE cur CURSOR FOR
    SELECT eno, salary FROM emp;
  DECLARE CONTINUE HANDLER FOR NOT FOUND
    SET done = 1;
  SET p_n = 0;
  OPEN cur;
  lp: LOOP
    FETCH cur INTO v_eno, v_sal;
    IF done = 1 THEN LEAVE lp; END IF;
    IF v_sal < 5000 THEN
      UPDATE emp SET salary = salary + 500
        WHERE eno = v_eno;
      SET p_n = p_n + 1;
    ELSEIF v_sal < 10000 THEN
      UPDATE emp SET salary = salary + 300
        WHERE eno = v_eno;
      SET p_n = p_n + 1;
    END IF;
  END LOOP lp;
  CLOSE cur;
END $$
DELIMITER ;
CALL sp_raise(@n);
SELECT @n, fn_dept_avg('D2');

CREATE VIEW v_unreturned AS
  SELECT br.rno, b.bname, br.bdate
  FROM borrow br JOIN book b ON br.bno = b.bno
  WHERE br.rdate IS NULL;
DELIMITER $$
CREATE FUNCTION fn_out(p_rno CHAR(2))
  RETURNS INT
  READS SQL DATA
BEGIN
  RETURN (SELECT COUNT(*) FROM borrow
          WHERE rno = p_rno AND rdate IS NULL);
END $$
CREATE PROCEDURE sp_return(IN p_rno CHAR(2),
  IN p_bno CHAR(2))
BEGIN
  UPDATE borrow SET rdate = CURDATE()
    WHERE rno = p_rno AND bno = p_bno
      AND rdate IS NULL;
  IF ROW_COUNT() > 0 THEN
    UPDATE book SET stock = stock + 1
      WHERE bno = p_bno;
  END IF;
END $$
DELIMITER ;
CALL sp_return('R1', 'B1');
SELECT * FROM v_unreturned;
SELECT fn_out('R1');

CREATE TABLE t_num (
  id INT AUTO_INCREMENT PRIMARY KEY,
  n  INT,
  sq INT
);
DELIMITER $$
CREATE PROCEDURE sp_fill(IN p_k INT)
BEGIN
  DECLARE i INT DEFAULT 1;
  WHILE i <= p_k DO
    INSERT INTO t_num(n, sq) VALUES (i, i * i);
    SET i = i + 1;
  END WHILE;
END $$
CREATE PROCEDURE sp_sum_odd(IN p_k INT,
  OUT p_s INT)
BEGIN
  DECLARE i INT DEFAULT 1;
  SET p_s = 0;
  REPEAT
    SET p_s = p_s + i;
    SET i = i + 2;
  UNTIL i > p_k
  END REPEAT;
END $$
DELIMITER ;
CALL sp_fill(10);
CREATE INDEX idx_sq ON t_num(sq);
SELECT * FROM t_num WHERE sq BETWEEN 20 AND 70;
CALL sp_sum_odd(9, @s);
SELECT @s;

