CREATE TRIGGER tr_o_ins AFTER INSERT ON orders
FOR EACH ROW
  UPDATE goods SET stock = stock - NEW.qty
  WHERE gno = NEW.gno;
CREATE TRIGGER tr_o_del AFTER DELETE ON orders
FOR EACH ROW
  UPDATE goods SET stock = stock + OLD.qty
  WHERE gno = OLD.gno;
CREATE TRIGGER tr_o_upd AFTER UPDATE ON orders
FOR EACH ROW
  UPDATE goods
  SET stock = stock + OLD.qty - NEW.qty
  WHERE gno = NEW.gno;
